  select lid, slug, name, type, 'published', (select id from public.areas ar where ar.slug = a.area), hook, what, coalesce(htb, '{}'), website, email, false, street, city, growth from a;
insert into public.listing_categories (listing_id, category_id) select a.lid, cat.id from a join public.categories cat on cat.slug = any(coalesce(a.categories, '{}'));
insert into public.listing_socials (listing_id, platform, handle, url) select a.lid, s->>'platform', s->>'handle', s->>'url' from a, jsonb_array_elements(coalesce(a.socials, '[]')) s;
update public.candidates cd set status = 'approved', listing_id = a.lid, reviewed_at = now() from a where cd.id = a.cid;
insert into public.chain_checks (candidate_id, listing_id, verdict, reasoning, admin_decision, decided_at) select cid, lid, 'local', reason, 'local', now() from a;
create temp table ch as select * from jsonb_to_recordset($j$[{"cid":"7454cfc7-708a-4eaf-893a-b7258737e88b","note":"Seed CSV says: \"Arizona-based mini chain - check\". Arizona-based with multiple out-of-state locations exceeds the 3+ outside-Nevada rule. Manual review, not an agent run."}]$j$::jsonb) as x(cid uuid, note text);
update public.candidates cd set status = 'chain', admin_note = ch.note, reviewed_at = now() from ch where cd.id = ch.cid;
insert into public.chain_checks (candidate_id, verdict, reasoning, admin_decision, decided_at) select cid, 'chain', note, 'chain', now() from ch;
select (select count(*) from a) as approved, (select count(*) from ch) as chains;
drop table a; drop table ch;
delete from public.listing_categories lc using public.categories b, public.listing_categories p, public.categories pz where lc.category_id = b.id and b.slug = 'bakery-desserts' and p.listing_id = lc.listing_id and p.category_id = pz.id and pz.slug = 'pizza' and (select type from public.listings where id = lc.listing_id) <> 'home_seller';
commit;
select status, count(*) from public.candidates group by status;
